+
+      if (invalidEntries.length > 0) {
+        invalidEntries[0].field.input.focus();
+        return;
+      }
+
+      form.reset();
+      Object.values(fields).forEach((field) => {
+        showFieldState(field, "");
+      });
+
+      submissionNote.textContent = "Thanks. Your support request is ready to send.";
+      submissionNote.setAttribute("aria-hidden", "false");
+      statusRegion.textContent = "Support request ready to send.";
+    });
