       const hasError = Boolean(message);
       field.error.textContent = message || field.error.textContent;
       field.error.hidden = !hasError;
       field.input.setAttribute("aria-invalid", hasError ? "true" : "false");
     }

     function validateField(field) {
       const message = field.validate(field.input.value);
       showFieldState(field, message);
       return message;
     }

     Object.values(fields).forEach((field) => {
       field.input.addEventListener("blur", () => {
         validateField(field);
       });

       field.input.addEventListener("input", () => {
         if (!field.error.hidden) {
           validateField(field);
         }
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();
       submissionNote.textContent = "";
       submissionNote.setAttribute("aria-hidden", "true");
       statusRegion.textContent = "";

       const invalidEntries = Object.values(fields)
         .map((field) => ({ field, message: validateField(field) }))
         .filter((entry) => entry.message);

       if (invalidEntries.length > 0) {
         invalidEntries[0].field.input.focus();
         return;
       }

       form.reset();
       Object.values(fields).forEach((field) => {
         showFieldState(field, "");
       });

       submissionNote.textContent = "Thanks. Your support request is ready to send.";
       submissionNote.setAttribute("aria-hidden", "false");
       statusRegion.textContent = "Support request ready to send.";
     });
   </script>
 </body>
